18	static bool mi_malloc_is_naturally_aligned( size_t size, size_t alignment ) {
19	  // certain blocks are always allocated at a certain natural alignment.
20	  // (see also `arena.c:mi_arenas_page_alloc_fresh`).
21	  mi_assert_internal(mi_alignment_is_valid(alignment));
22	  if (alignment > size) return false;
23	  const size_t bsize = mi_good_size(size);
24	  const bool ok = (bsize <= MI_PAGE_MAX_START_BLOCK_ALIGN2 && _mi_is_power_of_two(bsize)) ||             // power-of-two under N
25	                  (alignment==MI_PAGE_OSPAGE_BLOCK_ALIGN2 && (bsize % MI_PAGE_OSPAGE_BLOCK_ALIGN2)==0);  // or multiple of N
26	  if (ok) { mi_assert_internal((bsize & (alignment-1)) == 0); } // since both power of 2 and alignment <= size
27	  return ok;
28	}
