30	#if MI_GUARDED
31	static mi_decl_noinline mi_decl_restrict void* mi_theap_malloc_guarded_aligned(mi_theap_t* theap, size_t size, size_t alignment, bool zero, mi_page_t** ppage) mi_attr_noexcept {
32	  // use over allocation for guarded blocksl
33	  #if MI_THEAP_INITASNULL
34	  if mi_unlikely(theap==NULL) { theap = _mi_theap_empty_get(); }
35	  #endif
36	  mi_assert_internal(alignment > 0 && alignment < MI_PAGE_MAX_OVERALLOC_ALIGN);
37	  if mi_unlikely(alignment >= MI_PAGE_MAX_OVERALLOC_ALIGN || size > (MI_MAX_ALLOC_SIZE - MI_PADDING_SIZE - alignment)) {
38	    _mi_error_message(EOVERFLOW, "(guarded) aligned allocation request is too large (size %zu, alignment %zu)\n", size, alignment);
39	    return NULL;
40	  }
41	  const size_t oversize = size + alignment - 1;
42	  void* const base = _mi_theap_malloc_guarded(theap, oversize, zero, ppage);
43	  if (base==NULL) return NULL;
44	  void* const p = _mi_align_up_ptr(base, alignment);
45	  mi_track_align(base, p, (uint8_t*)p - (uint8_t*)base, size);
46	  mi_assert_internal(mi_usable_size(p) >= size);
47	  mi_assert_internal(_mi_is_aligned(p, alignment));
48	  return p;
49	}
