51	static void* mi_theap_malloc_zero_no_guarded(mi_theap_t* theap, size_t size, bool zero, mi_page_t** ppage) {
52	  #if MI_THEAP_INITASNULL
53	  if mi_unlikely(theap==NULL) { theap = _mi_theap_empty_get(); }
54	  #endif
55	  const size_t rate = theap->guarded_sample_rate;
56	  // only write if `rate!=0` so we don't write to the constant `_mi_theap_empty`
57	  if (rate != 0) { theap->guarded_sample_rate = 0; }
58	  void* p = _mi_theap_malloc_zero(theap, size, zero, ppage);
59	  if (rate != 0) { theap->guarded_sample_rate = rate; }
60	  return p;
61	}
