68	// Fallback aligned allocation that over-allocates -- split out for better codegen
69	static mi_decl_noinline void* mi_theap_malloc_zero_aligned_at_overalloc(mi_theap_t* const theap, const size_t size, const size_t alignment, const size_t offset, const bool zero, mi_page_t** ppage) mi_attr_noexcept
70	{
71	  mi_assert_internal(size <= (MI_MAX_ALLOC_SIZE - MI_PADDING_SIZE));
72	  mi_assert_internal(mi_alignment_is_valid(alignment));
73	
74	  void* p;
75	  size_t oversize;
76	  mi_page_t* page;
77	  if mi_unlikely(alignment > MI_PAGE_MAX_OVERALLOC_ALIGN) {
78	    // use OS allocation for large alignments and allocate inside a singleton page (not in an arena)
79	    // This can support alignments >= MI_PAGE_ALIGN by ensuring the object can be aligned
80	    // in the first (and single) page such that the page info is `MI_PAGE_ALIGN` bytes before it (and can be found in the _mi_page_map).
81	    if mi_unlikely(offset != 0) {
82	      // todo: cannot support offset alignment for very large alignments yet
83	      _mi_error_message(EOVERFLOW, "aligned allocation with a large alignment cannot be used with an alignment offset (size %zu, alignment %zu, offset %zu)\n", size, alignment, offset);
84	      return NULL;
85	    }
86	    oversize = (size <= MI_SMALL_SIZE_MAX ? MI_SMALL_SIZE_MAX + 1 /* ensure we use generic malloc path */ : size);
87	    // note: no guarded as alignment > 0
88	    p = _mi_theap_malloc_zero_ex(theap, oversize, zero, alignment, &page); // the page block size should be large enough to align in the single huge page block
89	    if (p == NULL) return NULL;
90	  }
91	  else {
92	    // otherwise over-allocate
93	    mi_assert_internal(size <= (MI_MAX_ALLOC_SIZE - MI_PADDING_SIZE) && alignment <= MI_PAGE_MAX_OVERALLOC_ALIGN);
94	    mi_assert_internal(size < SIZE_MAX - alignment); // `oversize` cannot overflow
95	    oversize = (size < MI_MAX_ALIGN_SIZE ? MI_MAX_ALIGN_SIZE : size) + alignment - 1;  // adjust for size <= 16; with size 0 and alignment 64k, we would allocate a 64k block and pointing just beyond that.
96	    p = mi_theap_malloc_zero_no_guarded(theap, oversize, zero, &page);
97	    if (p == NULL) return NULL;
98	  }
99	  mi_assert_internal(page == _mi_ptr_page(p));
100	  if (ppage!=NULL) { *ppage = page; }
101	
102	  // .. and align within the allocation
103	  const uintptr_t align_mask = alignment - 1;  // for any x, `(x & align_mask) == (x % alignment)`
104	  const uintptr_t poffset = ((uintptr_t)p + offset) & align_mask;
105	  const uintptr_t adjust  = (poffset == 0 ? 0 : alignment - poffset);
106	  mi_assert_internal(adjust < alignment);
107	  void* aligned_p = (void*)((uintptr_t)p + adjust);
108	
109	  // note: after the above allocation, the page may be abandoned now (as it became full, see `page.c:_mi_malloc_generic`)
110	  // and we no longer own it. We should be careful to only read constant fields in the page,
111	  // or use safe atomic access as in `mi_page_set_has_interior_pointers`.
112	  // (we can access the page though since the just allocated pointer keeps it alive)
113	  if (aligned_p != p) {
114	    mi_page_set_has_interior_pointers(page, true);
115	    // if (usable!=NULL) { 
116	    //   mi_assert_internal(*usable > adjust);
117	    //   if (*usable > adjust) { *usable = *usable - adjust; }
118	    //   mi_assert_internal(*usable >= size);
119	    // }
120	    #if MI_GUARDED
121	    // set tag to aligned so mi_usable_size works with guard pages
122	    if (adjust >= sizeof(mi_block_t)) {
123	      mi_block_t* const block = (mi_block_t*)p;
124	      block->next = MI_BLOCK_TAG_ALIGNED;
125	    }
126	    #endif
127	    _mi_padding_shrink(page, (mi_block_t*)p, adjust + size);
128	  }
129	  // todo: expand padding if overallocated ?
130	
131	  mi_assert_internal(mi_page_usable_block_size(page) >= adjust + size);
132	  mi_assert_internal(((uintptr_t)aligned_p + offset) % alignment == 0);
133	  mi_assert_internal(mi_usable_size(aligned_p)>=size);
134	  mi_assert_internal(mi_usable_size(p) == mi_usable_size(aligned_p)+adjust);
135	  #if MI_DEBUG > 1
136	  mi_page_t* const apage = _mi_ptr_page(aligned_p);
137	  void* unalign_p = _mi_page_ptr_unalign(apage, aligned_p);
138	  mi_assert_internal(p == unalign_p);
139	  #endif
140	
141	  // now zero the block if needed
142	  //if (alignment > MI_PAGE_MAX_OVERALLOC_ALIGN) {
143	  //  // for the tracker, on huge aligned allocations only from the start of the large block is defined
144	  //  mi_track_mem_undefined(aligned_p, size);
145	  //  if (zero) {
146	  //    _mi_memzero_(aligned_p, mi_usable_size(aligned_p));
147	  //  }
148	  //}
149	
150	  if (p != aligned_p) {
151	    mi_track_align(p,aligned_p,adjust,mi_usable_size(aligned_p));
152	    #if MI_GUARDED
153	    mi_track_mem_defined(p, sizeof(mi_block_t));
154	    #endif
155	  }
156	  return aligned_p;
157	}
