159	// Generic primitive aligned allocation -- split out for better codegen
160	static mi_decl_noinline void* mi_theap_malloc_zero_aligned_at_generic(mi_theap_t* const theap, const size_t size, const size_t alignment, const size_t offset, const bool zero, mi_page_t** ppage) mi_attr_noexcept
161	{
162	  mi_assert_internal(mi_alignment_is_valid(alignment));
163	  // we don't allocate more than MI_MAX_ALLOC_SIZE (see <https://sourceware.org/ml/libc-announce/2019/msg00001.html>)
164	  if mi_unlikely(size > (MI_MAX_ALLOC_SIZE - MI_PADDING_SIZE)) {
165	    _mi_error_message(EINVAL, "aligned allocation request is too large (size %zu, alignment %zu)\n", size, alignment);
166	    return NULL;
167	  }
168	
169	  // use regular allocation if it is guaranteed to fit the alignment constraints.
170	  // this is important to try as the fast path in `mi_theap_malloc_zero_aligned` only works when there exist
171	  // a page with the right block size, and if we always use the over-alloc fallback that would never happen.
172	  if (offset == 0 && mi_malloc_is_naturally_aligned(size,alignment)) {
173	    void* p = mi_theap_malloc_zero_no_guarded(theap, size, zero, ppage);
174	    mi_assert_internal(p == NULL || ((uintptr_t)p % alignment) == 0);
175	    const bool is_aligned_or_null = (((uintptr_t)p) & (alignment-1))==0;
176	    if mi_likely(is_aligned_or_null) {
177	      return p;
178	    }
179	    else {
180	      // this should never happen if the `mi_malloc_is_naturally_aligned` check is correct..
181	      mi_assert(false);
182	      mi_free(p);
183	    }
184	  }
185	
186	  // fall back to over-allocation
187	  return mi_theap_malloc_zero_aligned_at_overalloc(theap,size,alignment,offset,zero,ppage);
188	}
