196	// Primitive aligned allocation
197	static inline void* mi_theap_malloc_zero_aligned_at(mi_theap_t* const theap, const size_t size, const size_t alignment, const size_t offset, const bool zero, mi_page_t** ppage) mi_attr_noexcept
198	{
199	  // note: we don't require `size > offset`, we just guarantee that the address at offset is aligned regardless of the allocated size.
200	  if mi_unlikely(!mi_alignment_is_valid(alignment)) { // require power-of-two and multiple of void* (see <https://en.cppreference.com/w/c/memory/aligned_alloc#Notes>)
201	    return mi_error_bad_alignment(size, alignment, offset);
202	  }
203	
204	  #if MI_GUARDED
205	  #if MI_THEAP_INITASNULL
206	  if mi_likely(theap!=NULL)
207	  #endif
208	  if (offset==0 && alignment < MI_PAGE_MAX_OVERALLOC_ALIGN && mi_theap_malloc_use_guarded(theap,size)) {
209	    return mi_theap_malloc_guarded_aligned(theap, size, alignment, zero, ppage);
210	  }
211	  #endif
212	
213	  // try first if there happens to be a small block available with just the right alignment
214	  // since most small power-of-2 blocks (under MI_PAGE_MAX_BLOCK_START_ALIGN2) are already
215	  // naturally aligned this can be often the case.
216	  #if MI_THEAP_INITASNULL
217	  if mi_likely(theap!=NULL)
218	  #endif
219	  {
220	    if mi_likely(size <= MI_SMALL_SIZE_MAX && alignment <= size) {
221	      const uintptr_t align_mask = alignment-1;       // for any x, `(x & align_mask) == (x % alignment)`
222	      const size_t padsize = size + MI_PADDING_SIZE;
223	      mi_page_t* page = _mi_theap_get_free_small_page(theap, padsize);
224	      if mi_likely(page->free != NULL) {
225	        const bool is_aligned = (((uintptr_t)page->free + offset) & align_mask)==0;
226	        if mi_likely(is_aligned)
227	        {
228	          if (ppage!=NULL) { *ppage = page; }
229	          void* p = _mi_page_malloc_zero(theap, page, padsize, zero);
230	          mi_assert_internal(p != NULL);
231	          mi_assert_internal(((uintptr_t)p + offset) % alignment == 0);
232	          mi_track_malloc(p, size, zero);
233	          return p;
234	        }
235	      }
236	    }
237	  }
238	
239	  // fallback to generic aligned allocation
240	  return mi_theap_malloc_zero_aligned_at_generic(theap, size, alignment, offset, zero, ppage);
241	}
