343	// ------------------------------------------------------
344	// Aligned re-allocation
345	// ------------------------------------------------------
346	
347	static void* mi_theap_realloc_zero_aligned_at(mi_theap_t* theap, void* p, size_t newsize, size_t alignment, size_t offset, bool zero) mi_attr_noexcept {
348	  mi_assert(mi_alignment_is_valid(alignment));
349	  if mi_unlikely(!mi_alignment_is_valid(alignment)) { // require power-of-two (see <https://en.cppreference.com/w/c/memory/aligned_alloc>)
350	    return mi_error_bad_alignment(newsize,alignment,offset);
351	  }
352	  if (alignment <= sizeof(uintptr_t) && offset==0) return _mi_theap_realloc_zero(theap,p,newsize,zero);
353	  if (p == NULL) return mi_theap_malloc_zero_aligned_at(theap,newsize,alignment,offset,zero,NULL);
354	  const size_t size = mi_usable_size(p);
355	  if (newsize <= size && newsize >= (size - (size / 2)) && (((uintptr_t)p + offset) & (alignment-1)) == 0) {
356	    return p;  // reallocation still fits, is aligned and not more than 50% waste
357	  }
358	  else {
359	    // note: we don't zero allocate upfront so we only zero initialize the expanded part (at the cost of calling mi_usable_size)
360	    mi_page_t* newpage;
361	    void* const newp = mi_theap_malloc_zero_aligned_at(theap,newsize,alignment,offset,false/*zero?*/,&newpage);
362	    if (newp != NULL) {
363	      const size_t copy_size  = (newsize > size ? size : newsize);
364	      const size_t zero_start = (copy_size >= sizeof(intptr_t) ? copy_size - sizeof(intptr_t) : 0); // also set last word in the previous allocation to zero to ensure any padding is zero-initialized    
365	      const size_t usable     = _mi_page_usable_size(newpage,newp);
366	      mi_assert_internal(usable >= newsize); // use usable for zero'ing, issue #763
367	      if (zero && usable > zero_start) {
368	        // also set last word in the previous allocation to zero to ensure any padding is zero-initialized
369	        _mi_memzero((uint8_t*)newp + zero_start, usable - zero_start);
370	      }
371	      _mi_memcpy(newp, p, copy_size); // cannot be aligned due to abitrary offset... (todo: require offset to be a multiple of sizeof(void*)?)
372	      mi_free(p); // only free if successful
373	    }
374	    return newp;
375	  }
376	}
